"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Нескінченна прокачка: генерали й Маршал ★, рівні кар'єри, майстерність зброї й обвіси, медалі, щоденні контракти — екран «Кар'єра»",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Стратегія: плавний зум колесом, значки й підписи над юнітами (Alt — усі), панель «Війська / Будівлі» ліворуч",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"ПКМ — атака-рух, подвійний ПКМ — марш зі стрільбою на ходу; рідкісні накази — в «Ще накази ▾»; кнопки не дублюються",
"New in v6":"Нове у v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Стрільба як у шутерах: миттєві кулі, автомат 720 пострілів/хв, кулемет, віддача, приціл на ПКМ, магазини й перезарядка R, мітки влучань",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Важча гравітація, чуйний реактивний ранець, ривок на Z або подвійний ранець у повітрі; при переході в іншого бійця зброя більше не летить",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Інженери: виділи інженера, обери будівлю, постав креслення; екстрактори на рудних жилах; клік по «РУДА» — звідки дохід і як його прискорити",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Сірі кнопки можна натиснути — покажемо причину й кнопку-рішення; великі кнопки, смуга «У роботі», «▶ Керувати», Tab — єдина клавіша режимів",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Камера стратегії без ривків і перевертань, зум до курсору, мінікарту можна тягнути",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Нова техніка: рейдер «Шакал», РСЗВ «Град» (ракети-самонавідники), міномет «Молот»; у Рою — «Оса», «Вулик», «Требушет»",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Стратег не змінює накази без потреби й не спамить голосом; бої біля тебе; B — перекидання, Shift+B — у бій; компас, H — яка ціль",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Вільна гра (K) і дії наодинці (J), F2 — пресети; Esc — пауза й назад; збереження: слоти, експорт та імпорт файлу",
"New in v5.3":"Нове у v5.3",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Політ: гравітація далеко від метеорита сильніша, C у повітрі — гальмо, тяга кермує різкіше; більше не «зависаєш» у порталі",
"New in v5":"Нове у v5",
"Endless war by default and battle scale: normal, large, epic":"Нескінченна війна за замовчуванням і масштаб боїв: звичайний, великий, епічний",
"Save and load the battle (autosave every 3 minutes)":"Збереження й завантаження бою (і автозбереження кожні 3 хвилини)",
"Squadmates with callsigns: portraits, health and live chatter":"Загін із позивними: портрети, здоров'я й живі переговори",
"Fog of war in strategy, friends and foes outlined differently":"Туман війни в стратегії, свої та вороги підсвічені по-різному",
"Camera fly-over when switching, portal aurora instead of rings":"Проліт камери під час перемикання, сяйво порталу замість кілець",
"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Побічні завдання, короткий шлях через небо, модулі першої експедиції із припасами, кристали, лід у кратерах, пилові бурі",
"Training, cinema mode with video recording, escort vehicles from the strategist":"Навчання, кіно-режим із записом роликів, техніка супроводу від стратега",
