"Developer mode":"Режим розробника",
"(match will not count for career)":"(матч не потрапить у кар'єру)",
"Panel":"Панель",
"Battle":"У бій",
"The Consortium heavy gunner is now a real rigged 3D model: idles, walks, charges with his gun, fires on the move and falls when destroyed":"Важкий кулеметник Консорціуму тепер — справжня 3D-модель зі скелетом: стоїть, ходить, біжить зі зброєю, стріляє на ходу й гарно падає",
"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"Модель стоїть по нормалі до поверхні метеорита, повертає корпус за прицілом і тримає кулемет у руках; удалині анімація оновлюється рідше — FPS не падає",
"New in v6.5":"Нове у v6.5",
"Barracks":"Казарма",
"Infantry: assault squads, heavy gunners, snipers, scouts, drop pods; armor and weapon upgrades.":"Піхота: штурмові загони, важкі кулеметники, снайпери, розвідники, капсули; покращення броні та зброї.",
"Ore depot":"Склад руди",
"Builders drop crystals here. Place it next to a crystal field — shorter trips, more ore.":"Сюди інженери здають кристали. Став поруч із кристалічним полем — ближче носити, руди більше.",
"Tanks and vehicles. Requires Barracks.":"Танки й техніка. Потрібна Казарма.",
"Autonomous combat drones. Requires Barracks.":"Автономні бойові дрони. Потрібна Казарма.",
"Jetpacks II and Sky troopers (jetpack elite). Requires a Mech factory, unlocks at 6:00.":"Реактивні ранці II і Небесний десант (еліта на ранцях). Потрібен мех-завод, відкривається з 6:00 бою.",
"Forward base at an owned point: builders, crystal drop-off, reinforcement.":"Передова база біля своєї точки: інженери, здача кристалів, поповнення.",
"Unlocks at {0}":"Відкриється на {0} бою",
"Limit reached":"Ліміт: уже збудовано",
"Unlocks in {0}":"Відкриється за {0}",
"Jetpacks and aircraft unlock later — time to set up anti-air and turrets. Build Barracks and a Mech factory meanwhile.":"Реактивні ранці й авіацію відкривають не одразу — встигни поставити ППО й турелі. Поки будуй Казарму й мех-завод.",
"Lone heavy gunner":"Кулеметник-одинак",
