"A crystal field is depleted":"Кристалічне поле вироблене",
"carrying ore (+{0})":"несе руду (+{0})",
"mining crystals":"добуває кристали",
"No crystal field near a drop-off":"Немає кристалічного поля поблизу місця здачі",
"Mine crystals: the builder picks up a load at a green field and carries it to the HQ/depot. Or RMB the crystals.":"Добувати кристали: інженер набирає вантаж на зеленому полі й носить до штабу/складу. Або права кнопка миші по кристалах.",
"Gather":"Добувати",
