"Heavy bunker with AT gun":"Важкий бункер із ПТ-гарматою",
"A second bunker with an anti-tank gun (vehicles out to 110 m); the pillbox gets armour plates and the outpost +35% HP.":"Другий бункер із протитанковою гарматою (техніку до 110 м), дот обшито бронею, форпост міцніший на 35 %.",
"Support":"Підтримка",
"Repair-drone bay":"Ангар ремонтних дронів",
"Three repair drones fix friendly robots, vehicles and buildings within 28 m.":"Три дрони-ремонтники лагодять своїх роботів, техніку й будівлі в радіусі 28 м.",
"Force-field dome":"Силовий купол",
"A 24 m dome: friendlies inside take 38% less damage.":"Купол радіусом 24 м: свої всередині отримують на 38 % менше шкоди.",
"Recon":"Розвідка",
"Radio scanner":"Радіосканер",
"A scanner mast clears the fog of war within 150 m.":"Щогла зі сканером знімає туман війни на 150 м навколо.",
"Sniper & spotter tower":"Снайперська вежа-коригувальник",
"Vision 190 m, marks enemies for the whole army (160 m), artillery and MLRS are twice as accurate there, and a sniper on top shoots infantry.":"Огляд 190 м, мітить ворогів для всієї армії (160 м), артилерія й РСЗВ по відміченому району б'ють удвічі кучніше, снайпер на вежі стріляє по піхоті.",
"Armour plating":"Бронеплити",
