"Defence turrets":"Турелі оборони",
"4 twin turrets on the HQ platform: infantry, drones and light vehicles within 95 m.":"4 здвоєні турелі на платформі штабу: піхота, дрони, легка техніка до 95 м.",
"Faster orbital drop":"Прискорений орбітальний скид",
"A homing beacon: squads and solos from the barracks, builders and the drop pod are 35% faster, the pod is 25% cheaper.":"Маяк наведення: загони й одинаки з казарми, інженери та десантна капсула готові на 35 % швидше, капсула на 25 % дешевша.",
"Ore refinery columns":"Колони переробки руди",
"Income +25%.":"Дохід +25 %.",
"Global radar":"Глобальний радар",
"Every 40 s a pulse reveals every enemy on the meteor for 6 s.":"Раз на 40 с — імпульс: усі вороги на метеориті видні 6 с.",
"Comms array":"Антени зв'язку",
"+2 command points now and +1 more every 40 s (strikes, strategist powers).":"+2 очки командування (ОК) одразу й ще +1 кожні 40 с (удари, здібності стратега).",
"The outpost is still being built":"Форпост ще будується",
