"Pod on point {0}: {1}{2}{3}. The builder can place an outpost (V) and pick an upgrade branch.":"Капсула на точці {0}: {1}{2}{3}. Інженер може поставити форпост (V) і обрати гілку поліпшень.",
"HQ radar: every enemy is visible for 6 s":"Радар штабу: усі вороги видні 6 с",
