"Outpost upgrades":"Поліпшення форпосту",
"point":"точка",
"Pick a branch — every point gets its own speciality:":"Обери гілку — у кожної точки своя спеціалізація:",
"Building — click to cancel":"Будується — клік: скасувати",
"A builder near the outpost (30 m) does the upgrade.":"Поліпшення будує інженер поруч із форпостом (30 м).",
"Send a builder":"Прислати інженера",
"Builders nearby":"Інженерів поруч",
"{0} is heading to the outpost":"{0} іде до форпосту",
"From the very start your base has the whole army, one of each: sky troopers, lone heavy gunner, sniper, scout, drone, raider, MLRS, mortar (plus assault squads and a tank) — possess anyone right away":"З самого початку бою на базі стоїть уся армія по одному: десант, кулеметник-одинак, снайпер, розвідник, дрон, рейдер, РСЗВ, міномет (і штурмові загони з танком) — керуй будь-ким одразу",
"\"Custom order\" for possession (pause menu, ☰ on the phone): each class has a number, 1 is the top; ▲▼ change it, ✕ means never. After death and on X you get the unit closest to the fight in that order":"«Свій порядок» керування (пауза, на телефоні ☰): у кожного класу номер, 1 — головний; ▲▼ змінюють, ✕ — ніколи. Після загибелі та за X береться найближчий до бою боєць за цим порядком",
"Bots are no longer snipers: they miss at range, on the move, against runners and targets in cover; bullets whizz past you and kick up dirt and cover nearby. Explosions knock you down: flinch, to one knee, off your feet and back up":"Боти більше не снайпери: схибляють здалеку, на бігу, по тих, хто біжить і в укритті; повз тебе кулі свистять, б'ють у землю й укриття поруч. Вибухи збивають з ніг: здригання, на коліно, з ніг і підйом",
"Capture a point and a pod drops a squad and a builder. An outpost on the point upgrades along one branch: defence (MG bunker → heavy bunker with AT gun), support (repair drones → force-field dome), recon (radio scanner → sniper & spotter tower)":"Захопив точку — капсула із загоном та інженером. Форпост на точці прокачується однією гілкою: оборона (дот → бункер із ПТ-гарматою), підтримка (ремонтні дрони → силовий купол), розвідка (радіосканер → снайперська вежа)",
"The HQ upgrades too: armour plating, defence turrets, faster orbital drop, +25% income, global radar, comms array (+command points). The AI does the same":"Штаб теж прокачується: бронеплити, турелі, прискорений орбітальний скид, дохід +25 %, глобальний радар, антени зв'язку (+очки командування). ШІ робить те саме",
"New in v7.0":"Нове у v7.0",
"Your base has one of every unit and vehicle: sky troopers, sniper, scout, drone, raider, MLRS, mortar. Select any and {0} — try them before you even build.":"На базі по одному бійцю й машині кожного типу: десант, снайпер, розвідник, дрон, рейдер, РСЗВ, міномет. Виділи будь-якого й {0} — спробуй, поки не відбудувався.",
"POSSESS":"КЕРУЙ",
"Point {0}: a builder landed with the pod. Select it and place an \"Outpost\"{1} by the point — then pick an upgrade branch.":"Точка {0}: з капсули висадився інженер. Виділи його й постав «Форпост»{1} біля точки — потім обереш гілку поліпшень.",
"OUTPOST":"ФОРПОСТ",
"The outpost is ready — select it and pick a branch: ⛨ Defence (MG bunker, AT bunker), ✚ Support (repair drones, force-field dome) or ◎ Recon (scanner, sniper tower). A builder nearby does the work.":"Форпост готовий — виділи його й обери гілку: ⛨ Оборона (дот, бункер із ПТ-гарматою), ✚ Підтримка (ремонтні дрони, силовий купол) або ◎ Розвідка (сканер, снайперська вежа). Будує інженер поруч.",
"UPGRADE":"ПОЛІПШИТИ",
"The HQ is a \"super point\": select it{0} — armour, turrets, faster drops, +25% income, radar, comms.":"Штаб — «суперточка»: виділи його{0} — бронеплити, турелі, швидший скид, дохід +25 %, радар, антени зв'язку.",
"☰ → \"Possession\": turn on \"Custom order\" and choose who you take after death — #1, #2… ✕ means never.":"☰ → «Керування»: увімкни «Свій порядок» і вирішуй, ким керувати після загибелі — №1, №2… ✕ — ніколи.",
"Esc → pause → \"Custom order\": choose who you take after death and on X — #1, #2… ✕ means never.":"Esc → пауза → «Свій порядок»: вирішуй, ким керувати після загибелі та за X — №1, №2… ✕ — ніколи.",
