"Voice of hints & curator":"Голос підказок і Наставника",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Телефон: три режими стиків. Лише лівий — «авто» (сильний магніт, але кулі слабші). Лише правий — приціл вмикається сам, магніт сильніший, стрільба точніша. Обидва разом — без прицілу, магніт і точність менші. Кнопка 👁 праворуч — сховати/повернути інтерфейс.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Телефон: стратегію спрощено — лише інженер і будівлі. Ліворуч картки (інженер, штаб, казарма…): дотик — камера летить до нього, внизу одразу що будувати/виробляти. «У бій» — ліворуч угорі. Армія воює сама. Повна стратегія — Налаштування → Телефон.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Керування — два прапорці: «Загони» і «Техніка» (на телефоні техніка за замовчуванням вимкнена — її водить ШІ). Якщо техніку вимкнено, E (на телефоні — кнопка праворуч) поруч зі своєю машиною — сісти за її гармату: машина їде сама, ти стріляєш. Старий «свій порядок класів» — у «Розширених». Під час керування юніт відповідає по рації.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Розумні підказки: базові самі згасають після 2-го запуску, але гра підкаже функцію, якою ти так і не користуєшся. Прапорці: базові / просунуті / рідкісні, окремо — голос підказок і Наставника.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Рефлекс заряджається від убивств (серія — сильніше). Напарники відстали або загинули — стратег десантує до тебе нових (дорожче за звичайне поповнення). Графіку й звук v7.2gfx влито: вибухи клубами, дим, уламки, акустика шахт і кратерів. Дата збірки — справжня.",
