"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Кар'єра й збереження не змінюються. У бою це саме меню — кнопка «🛠 Меню» угорі праворуч{0}.",
"New developer match":"Новий матч розробника",
"all unlocked, endless ore, instant build, arsenal":"усе відкрито, руда без кінця, миттєве будівництво, арсенал",
"Trainings — all 4":"Навчання — усі 4",
