"Cinema: split screen":"Кіно: спліт-екран",
"strategist bot left, shooter bot right":"ліворуч бот-стратег, праворуч бот-стрілець",
"Cinema: everything built":"Кіно: усе збудовано",
"both bases built and upgraded — for footage":"обидві бази збудовано й прокачано — для зйомки",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Кіно-режим — спліт-екран: ліворуч бот-стратег (вигляд зверху на базу й армію), праворуч бот-стрілець від першої особи. Кнопки внизу (і клавіші S, P): «Спліт-екран» і «★ Усе збудовано» — обидві бази збудовано й прокачано для зйомки.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Ядра й тунелів крізь метеорит більше немає — метеорит суцільний, бій лише на поверхні.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Телефон: 👁 ховає інтерфейс, але залишає реактивний ранець, ⇆, стіки та маркер завдання. «◎ Приціл» (лише правий палець) — помітно сильніший і ширший магніт; сила магніта для трьох режимів — Налаштування → Керування → «Розширені». За гарматою машини кнопка називається «Злізти».",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Навчання: на телефоні — лише телефонні, на ПК — лише ПК. Усі 4 — у меню «🛠 Розробник». Режим розробника й Арсенал об'єднано в одне меню (у бою — «🛠 Меню» вгорі праворуч, на ПК ще F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Стилі графіки «Dendy (8-біт)» і «16-біт»: Налаштування → Графіка → «Стиль графіки» (деталі — кнопка ⚙). Якщо в перші ~10 с матчу FPS нижче 24 — Dendy вмикається сам (нижче 20 і далі — ще більший піксель, 120 рядків); плашка «повернути звичайну» назавжди повертає звичайну графіку. Твій вибір у меню завжди важливіший.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D-моделі оточення (руїни, техніка, укріплення) — лише ті, що отримали хороші оцінки; вантажаться на вимогу з інтернету. Вимкнути: Налаштування → Графіка → «Нові 3D-моделі оточення».",
