"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Будівництво піхотинцями: E (на телефоні «Увійти») біля свого будівництва — піхотинець будує сам, побратими поруч допомагають. Якщо інженери зайняті, стратег сам попросить допомогти — мітка «БУДОВА».",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Мітки стратега: стратег ставить ⌖ на скупчення ворогів поруч із тобою — за 8 с туди б'є артилерія, а свої РСЗВ «Град» поблизу дають залп. Твій артилерійський удар зі стратегії — теж із підтримкою «Градів».",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Схованки зі зброєю у вантажних контейнерах і впалих супутниках (📦 видно з 70 м): E — кулемет на 90 с, запальні патрони або ракети, плюс повні гранати. Повзком: Ctrl — лягти / підвестися (нижче, тихіше, точніше, але повільно).",
