"The HUD stays sharp; the Dendy style is also faster (fewer pixels).":"Інтерфейс залишається чітким; стиль Dendy ще й швидший (менше пікселів).",
"That is not the sky above you. It is a portal to the enemy.":"Над тобою — не небо. Це портал до ворога.",
