"Play now":"Грати",
"straight into battle":"одразу в бій",
"Camera shake":"Тряска камери",
"Slow-mo on major kills":"Слоу-мо на важливих вбивствах",
"\"What to do now\" hint":"Підказка «що робити зараз»",
"from blasts and hits, gentle":"від вибухів і ударів, м'яка",
"last enemy nearby, tank, HQ":"останній ворог поруч, танк, штаб",
"corner; F7 — collapse":"у кутку; F7 — згорнути",
"Link copied":"Посилання скопійовано",
"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"«▶ Грати» — перша кнопка меню: короткий проліт під небом-порталом — і одразу в бій (пропуск — будь-яка клавіша або дотик).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Влучання відчуваються: металевий звук і іскри, мітка вбивства біля прицілу (у голову — жовта), серія ×N, плавна тряска від вибухів, слоу-мо на важливих вбивствах. Тряску, слоу-мо й підказку можна вимкнути в Налаштуваннях.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Підсумок матчу: час, знищення, найкраща серія, ★ MVP і найкращий загін, картка матчу — «⇪ Поділитися», PNG або посилання на гру.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Підказка «що робити зараз» ліворуч під ресурсами: наказ стратега, точка для захоплення, наступ Рою. ✕ або F7 — згорнути.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Бій зберігається сам, якщо закрити або згорнути вкладку, — у меню «⟲ Продовжити».",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Версія v7.5 залишилась у меню «🕘 Версія гри» — якщо нова не сподобається. Анонімна статистика (без імен і пошти) тепер надсилається; вимкнути — в Налаштуваннях.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"«Грати», відгук влучань, підсумок матчу з карткою, підказка «що робити», автозбереження",
"and older: v7.5, v7.4, milestones v1–v7.0":"і старіші: v7.5, v7.4, віхи v1–v7.0",
"New in v7.6":"Нове у v7.6",
"NEW IN v7.6":"НОВЕ У v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Вибір фракції перед матчем: «Консорціум» (важка піхота в силовій броні, броня й артилерія) або «Рій» (швидкість, зграї дронів, важкі постріли зі спотворенням). ШІ грає за іншу. Вибір запам'ятовується.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"У кожної фракції своя техніка й унікальне: у Консорціуму — танк «Носоріг» і «Керамітові плити», у Рою — «Зграя дронів» і «Фазові ранці». Баланс перевірено матчами ботів.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Воронки від вибухів: артилерія, ракети та гармати танків риють ями в метеориті — по них можна ходити й їздити, в них можна сховатися.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Вигляд від 3-ї особи для піхотинця (V, запам'ятовується; на телефоні — Керування) і плавна камера техніки з міткою, куди влучить гармата.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"Версія v7.6 залишилася в меню «🕘 Версія гри» — якщо нова не сподобається.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Фракції Консорціум / Рій з вибором перед матчем, воронки від вибухів, вигляд від 3-ї особи",
"and older: v7.6, v7.5, milestones v1–v7.0":"і старіші: v7.6, v7.5, віхи v1–v7.0",
