"dormant":"спить",
"Anomaly ahead! The vein is singing — go around!":"Аномалія попереду! Жила співає — обходимо!",
"Hear that hum? A singing vein. Keep clear!":"Чуєте гул? Співуча жила. Не підходити!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Аномалія! Повітря крутить — це вир, обходь!",
"Rocks floating in the air… A whirlpool! Stay out!":"Каміння висить у повітрі… Вир! Не лізь!",
"Anomaly ahead — it is crackling with current!":"Аномалія попереду — тріщить струмом!",
"Rods and lightning — a Crackler. It loves armour!":"Штирі й блискавки — Тріскун. Броню він любить!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Аномалія! Земля тремтить від жару — Жаровня!",
"Careful, a Brazier underfoot!":"Обережно, під ногами Жаровня!",
"Anomaly — green mist! Acid, hold your breath!":"Аномалія — зелений туман! Кислота, не дихаємо!",
"The mist is drifting our way, go around!":"Туман повзе до нас, обходимо!",
"Anomaly! The air is like glass — a Lens, it bends bullets!":"Аномалія! Повітря як скло — Лінза, кулі гне!",
"Everything is warping… a Lens nearby!":"Картинка пливе… Лінза поруч!",
"Ha! An enemy walked right into the anomaly!":"Ха! Ворог поліз прямо в аномалію!",
"Got him! Lure them into anomalies!":"Попався! Заманюй їх в аномалії!",
"Beautiful zap! One less tin can.":"Гарно жахнуло! Мінус залізяка.",
"The anomaly got me!":"Мене зачепило аномалією!",
"Ow! Don't go in there!":"Ай! Не лізьте туди!",
"Discharged! It is dormant now.":"Розрядив! Тепер вона спить.",
"Clear, the anomaly is discharged.":"Чисто, аномалію розряджено.",
"They say veins hide artifacts. Only first the vein sings…":"Кажуть, у жилах ховають артефакти. Тільки спочатку жила співає…",
"Throw a bolt first, then walk. Old habit.":"Кидай болт, потім іди. Стара прикмета.",
"throw a bolt":"кинути болт",
"📦 Supply drop: landing in 4 seconds":"📦 Ящик постачання: скидання через 4 секунди",
