"Recon: scanning the area":"Розвідка: скануємо район",
"\"Grad\": target received, salvo!":"«Град»: ціль прийнято, залп!",
"keep clear!":"тримайся подалі!",
"Strategist: dropping you a supply crate nearby":"Стратег: скидаю тобі ящик постачання, поруч",
