"Pause: resume, restart, training, graphics, settings, main menu":"Пауза: продовжити, заново, навчання, графіка, налаштування, головне меню",
"Menu: pause, restart, training, graphics, settings":"Меню: пауза, заново, навчання, графіка, налаштування",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Тримай палець на землі ~0,3 с — телефон здригнеться й з'явиться жовте кільце — і, не відпускаючи, веди: вийде рамка. Або кнопка «Рамка» праворуч. Можна й просто торкнутися загону.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Для повного екрана на iPhone: «Поділитися» ⬆ → «На початковий екран» — гра відкриється без панелей Safari.",
"Open portal-meteor.pages.dev for that.":"Відкрий для цього сайт portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Дотик — виділити · дотик по землі — іти · тримай — меню наказів · тримай і веди — рамка · 2 пальці — масштаб",
"Robo-ninja":"Робо-ніндзя",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Героїня-вбивця: ривки-телепорти, катана, сюрикени. Сама стрибає по зонах ворога й ріже роботів. 1 на сторону.",
"Shadow protocol":"Протокол «Тінь»",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Дослідження: відкриває робо-ніндзя в Казармі. Потрібен готовий мех-завод.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Героїня (1 на сторону): сама телепортується по зонах ворога й ріже роботів; можна взяти керування й грати вручну.",
"is ready. She works on her own (AUTO) — possess her to play manually":"готова. Працює сама (АВТО) — візьми керування, щоб грати вручну",
"Robo-ninja ready for action":"Робо-ніндзя готова до бою",
"⚠ Intel: the enemy has a robo-ninja!":"⚠ Розвідка: у супротивника з'явилася робо-ніндзя!",
"Warning! The enemy has a robo-ninja. Stay together":"Увага! У супротивника робо-ніндзя. Тримайтеся разом",
"cyber blinks":"кібер-ривки",
