"The two ninjas have met in a duel!":"Дві ніндзя зійшлися в дуелі!",
"⚔ Duel won! Our ninja prevails":"⚔ Дуель виграно! Наша ніндзя сильніша",
"⚔ Duel lost…":"⚔ Дуель програно…",
"ninja duel":"дуель ніндзя",
