"Teleport":"Телепорт",
"Teleport: aim at the ground (up to 150 m)":"Телепорт: наведи приціл на землю (до 150 м)",
"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ АВТО: сама стрибає по зонах ворога й ріже. Джойстик / WASD — пауза 1.5 с",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Ручне: дотик по ворогу — ривок і удар, свайп — змах, 🛡 — блок",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Ручне керування: ліва кнопка миші — катана, права кнопка миші — блок, Shift — ривок, Q — сюрикени, G — телепорт",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ніндзя: дотик по ворогу — ривок і удар, свайп праворуч — змах, ● — удар, 🛡 — блок (вчасно = парирування), ⇑ — ривок, ✦ — сюрикени, ◎ — телепорт, АВТО — сама",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ніндзя: ліва кнопка миші — катана (утримуй — важкий удар), права кнопка миші — блок (вчасно = парирування), Shift/Z — ривок, Q — сюрикени, G — телепорт до прицілу, стрибок у повітрі — подвійний / біг по стіні, {0} — АВТО",
