"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Радіо Portal Meteor: 100+ треків EDMITRY прямо в грі — кнопка 📻 (ПК: клавіша 5, [ ] — трек). Музика підвантажується з мережі й не обтяжує гру; гучність і автозапуск — у налаштуваннях, є посилання «Слухати в Spotify».",
