"Radio Portal Meteor on/off ([ ] — track, Shift+[ ] — volume)":"Радіо Portal Meteor увімк/вимк ([ ] — трек, Shift+[ ] — гучність)",
"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 праворуч — Радіо Portal Meteor: музика EDMITRY під час бою.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Радіо Portal Meteor: музика EDMITRY під час бою. [ ] — трек.",
"Radio Portal Meteor (EDMITRY): volume":"Радіо Portal Meteor (EDMITRY): гучність",
"Radio: start by itself in battle":"Радіо: вмикати саме в бою",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Робо-ніндзя: кіборг із катаною. Відкривається в Казармі дослідженням «Протокол „Тінь“» (потрібен мех-завод). Сама телепортується в зони ворога, розрубує ворогів навпіл (без крові — іскри), робить ривки, кидає сюрикени, б'ється в дуелях із ворожим ніндзя. Візьми її під контроль — режим АВТО або ручне керування (на телефоні — свої кнопки).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Радіо Portal Meteor: 103 треки EDMITRY прямо в грі. Клавіша 5 (перепризначається), на телефоні — ☰ → Налаштування → Звук. Гучність і «вмикати саме в бою» — у налаштуваннях; музика тихішає на вибухах і під голос рації.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Нові мови: узбецька й таджицька — повністю; китайська, іспанська, португальська — частково. Новий вибір мови в меню поруч із «Новий матч».",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Телефон: «сховати значки» 👁 збирає решту кнопок в акуратну колонку біля правого краю; портрет більше не налазить; iPhone — гра не конфліктує з жестами Safari, а «Поділитися → На екран „Додому“» запускає її на весь екран.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Із v7.8.1: меню ☰ в куті (пауза, заново, навчання, графіка), без авто-Dendy, кнопка дії ✋ на телефоні. v7.8.1 і v7.8 лишилися в меню «🕘 Версія гри».",
"Robo-ninja, EDMITRY radio, Uzbek and Tajik, phone and iPhone UX":"Робо-ніндзя, радіо EDMITRY, узбецька й таджицька, зручність телефона та iPhone",
