"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"Зона вогню радіусом 12 м горить 9 секунд: урон з часом, придушення, дим. Через 2,5 с. Підпалює метан.",
