"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Свої просять допомоги й винагороджують, герої дають квести, затяжний фронт ламають операцією",
"A request":"Прохання своїх",
"Breakthrough":"Перелом бою",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Свої іноді просять допомоги: голос по радіо, картка «ПРОХАННЯ» та маркер ✋. Загін притисли — знищ ворогів поруч із ним. Нагорода: боєць капсулою з бази, ствол із кузова багі, місце стрільця або прикриття з орбіти. Не хочеш — ✕ або просто ігноруй.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Ветеран-розвідник «Сова» пропонує квест. Y — прийняти (N — відмова). Іди до мітки ★, зніми охорону й постій біля пілота 3 с — він стане у твій загін.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Фронт став — штаб пропонує перелом. Y — прийняти. Утримуй ретранслятор 8 с без ворогів поруч: карта ворога видна 60 с. Генератор — турелі ворога мовчать 2 хв. У «Стратегу» — «Видати загону». Ворог теж так уміє: стеж за ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Свої просять допомоги: картка «ПРОХАННЯ» та маркер ✋. Знищ ворогів поруч із притиснутим загоном — отримаєш нагороду. ✕ — пропустити.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Герой «Сова» пропонує квест — торкнись «Прийняти». Іди до ★, зніми охорону, постій біля пілота.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Фронт став — торкнись «Прийняти» й утримуй ретранслятор 8 с: карта ворога відкриється на хвилину.",
