"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. Грай і думай уголос: що незрозуміло, що дратує, що подобається. У куті екрана — версія, час і FPS: за ними запис звіряється з нотатками.",
