"All settings":"Усі налаштування",
"Feedback & notes":"Відгук і нотатки",
"not done yet":"не пройдено",
"you fight yourself":"сам у бою",
"you lead one squad":"ведеш один загін",
"you command the whole army from above":"командуєш усією армією зверху",
"Want to command the army?":"Хочеш командувати армією?",
"Unlock the Strategist mode: look from above and give orders to the whole army.":"Відкрити режим «Стратег»: дивишся зверху й віддаєш накази всій армії.",
"Want to lead one squad?":"Хочеш вести один загін?",
"Unlock the Commander mode: camera over a squad, tap where to go.":"Відкрити режим «Командир»: камера над загоном, дотик — куди йти.",
"Yes":"Так",
"Later":"Пізніше",
"You run and shoot yourself. That is how you have played so far.":"Ти сам біжиш і стріляєш. Так ти грав досі.",
"Look from above and command the whole army: build the base, send squads. The army also fights on its own.":"Дивишся зверху й командуєш усією армією: будуєш базу, надсилаєш загони. Армія й без тебе воює сама.",
"You lead one squad: the camera is above it, tap the ground to move.":"Ведеш один загін: камера над ним, дотик по землі — куди йти.",
"The mode button is at the top right: tap for the next mode.":"Кнопка режиму — угорі праворуч: дотик — наступний режим.",
"Next":"Далі",
"Got it":"Зрозуміло",
"buttons":"кнопки",
"clean":"чисто",
"Messages":"Повідомлення",
"nothing yet":"поки порожньо",
"tap to close":"дотик — закрити",
"Third-person view — tap 🎥 to go back":"Вигляд від 3-ї особи — натисни 🎥, щоб повернутися",
"Third-person view — {0} to go back":"Вигляд від 3-ї особи — {0}, щоб повернутися",
"the gamepad view button or ":"кнопка вигляду на геймпаді або ",
"key ":"клавіша ",
"Hint hidden — tap «?» to open it. To leave the lesson: ☰ → «Leave lesson»":"Підказку згорнуто — «?» відкриє її знову. Вийти з уроку: ☰ → «Вийти з уроку»",
"◎ precise":"◎ точно",
"○ running":"○ біг",
"◉ run + aim":"◉ біг + приціл",
"Commander mode, faction bosses, living meteor (terrain, biomes, weather, anomalies, fauna), living world; faster, gamepad, tablet, encyclopedia, feedback mode, simple phone interface":"Режим «Командир», боси фракцій, живий метеорит (рельєф, біоми, погода, аномалії, фауна), живий світ; швидше, геймпад, планшет, енциклопедія, режим відгуку, простий інтерфейс для телефона",
"Three modes on one button: Shooter (you fight yourself), the new Commander (lead one squad, 4 abilities per unit type) and Strategist. On the phone — a simple interface: fewer buttons, modes unlock during the battle.":"Три режими однією кнопкою: Стрілець (сам у бою), новий Командир (ведеш один загін, у кожного типу 4 здібності) і Стратег. На телефоні — простий інтерфейс: менше кнопок, режими відкриваються по ходу бою.",
"Living meteor: rocks, ridges, a hangar in a mesa, lava / ice / methane lakes, three biomes, local weather, new anomalies and native fauna.":"Живий метеорит: скелі, пасма, ангар у столовій горі, озера лави, льоду й метану, три біоми, місцева погода, нові аномалії та місцева фауна.",
"Factions play differently: the Swarm digs tunnels and regenerates, the Consortium builds barriers and repairs. From minute 12 — the Bastion and Reaper bosses; you can possess your own.":"Фракції стали різними: Рій риє тунелі й лікується, Консорціум ставить бар'єри й лагодить техніку. З 12-ї хвилини — боси «Бастіон» і «Жнець»; у свого можна вселитися.",
"Living world: your troopers ask for help over the radio (with a reward), heroes give quests, a stalled front gets a \"Breakthrough\" operation. Capsules, crates and strikes launch from the base through the sky portal.":"Живий світ: свої бійці просять допомоги по радіо (з нагородою), герої дають завдання, за застою фронту — операція «Прорив». Капсули, ящики й удари стартують із бази через небесний портал.",
"Faster (a frame up to 2x cheaper), gamepad in every mode, tablet layout, an encyclopedia of everything in the game, feedback mode — a note with a screenshot on one key.":"Швидше (кадр до 2 разів дешевший), геймпад в усіх режимах, розкладка для планшета, енциклопедія всього в грі, режим відгуку — нотатка зі скриншотом однією клавішею.",
"All new texts are translated into Uzbek, Tajik, Chinese, Spanish, Portuguese and Hebrew. The v7.9 ninja and radio stay; v7.9 is in the \"🕘 Game version\" menu.":"Усі нові тексти перекладено узбецькою, таджицькою, китайською, іспанською, португальською та івритом. Ніндзя й радіо v7.9 на місці; v7.9 — у меню «🕘 Версія гри».",
